head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.colorCnt = 0; // 조회한 이후에만 컬럼에  color 변경하기 위한 변수
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gUpDepCd;
scwin.gIsurCd;

// 컬럼 컬러 구분을 위한 변수
scwin.check1, scwin.check2, scwin.check3, scwin.check4, scwin.check5, scwin.check6, scwin.check7, scwin.check8, scwin.check9, scwin.check10, scwin.check11, scwin.check12, scwin.check13, scwin.check14, scwin.check15, scwin.check16, scwin.check17;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        scwin.init();
        $c.cm.fn_com_isur(txb_isur_cd, txb_COM_NM);
        scwin.allDisCheck();
        scwin.showGridField('HIDDEN');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "";
    for (let i = yyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_FISCYY.CBData = str;
    rdo_MKT_ID.setValue(js_market);
    if (js_market === "9") {
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.setValue("1");
    } else {
        // 콘트롤 잠그기.
        $c.cm.setColumnProp(grd_XBRL2, "MKT_NM", "Show", false);
        rdo_MKT_ID.setDisabled(true);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listNewsflashFinance();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26300.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name dts_XBRL_OnLoadCompleted
 * @description dts_XBRL 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_XBRL_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.dts_XBRL_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_XBRL_OnLoadError
 * @description dts_XBRL 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_XBRL_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_XBRL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26300.dts_XBRL_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_XBRL2_OnDblClick
 * @description grd_XBRL2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_XBRL2_OnDblClick = async function(row, colid) {
    try {
        scwin.gIsurCd = dts_XBRL.getCellData(row, "ISUR_CD");
        const AcptNo = dts_XBRL.getCellData(row, "ACPT_NO");

        // alert(dts_XBRL.NameValue(row,"NONOPERREVENUES1"));
        // alert(dts_XBRL.NameValue(row,"NONOPEREXPENSES1"));
        if (colid === "ACPT_NO") {
            await $c.stf.openDisclViewer(AcptNo, "R");
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26300.grd_XBRL2_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26300.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name grd_XBRL2_OnUserColor
 * @description grd XBRL2 On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_XBRL2_OnUserColor = function(row, colid) {
    try {
        // var colorName = "#CBFF75";
        let colorName = "#77FF88"; // 11FF00";

        // 2009.03.27 happyhan 추가
        if (dts_XBRL.getCellData(row, "ACPT_NO") === null || dts_XBRL.getCellData(row, "ACPT_NO") === undefined) {
            colorName = "#ffffff"; // 데이타가 없으면 흰색으로

        }

        // 2009.03.27 happyhan 추가 : 회사정보결산월과 xbrl 재무정보의 결산월 비교
        if (colid === "acolor0") {
            const mm1 = dts_XBRL.getCellData(row, "ACNTCLS_MM");
            const mm2 = dts_XBRL.getCellData(row, "ACNTCLS_MMDD1");
            if (scwin.colorCnt > 0 && mm1 !== mm2) {
                return colorName; // 연두색
            } else {
                //    return decode(row-tointeger(row/2)*2,0,'#f2f5f9',1,'#ffffff');
                /*
                if ( row - Math.int( row/2) *2 == 0 ) return "#f2f5f9"
                else return "#ffffff";
                 */
                return "#ffffff";
            }
        }
        if (colid === "acolor1") {
            scwin.check1 = dts_XBRL.getCellData(row, "AUDT_OPIN_TP_NM");
            if (scwin.colorCnt > 0 && scwin.check1 !== "적정" && scwin.check1 !== "의견거절" && scwin.check1 !== "한정" && scwin.check1 !== "부적정") {
                return colorName; // 연두색
            } else {
                //    return decode(row-tointeger(row/2)*2,0,'#f2f5f9',1,'#ffffff');
                /*
                if ( row - Math.int( row/2) *2 == 0 ) return "#f2f5f9"
                else return "#ffffff";
                 */
                return "#ffffff";
            }
        }
        if (colid === "acolor2") {
            // BS 당기
            scwin.check2 = dts_XBRL.getCellData(row, "CURTRM_BS");
            if (scwin.colorCnt > 0 && scwin.check2 !== "" && scwin.check2 !== "0") {
                return colorName;
            } else {
                return "#ffffff";
            }
        }
        if (colid === "acolor3") {
            // BS 전기
            scwin.check3 = dts_XBRL.getCellData(row, "FSTTRM_BS");
            if (scwin.colorCnt > 0 && scwin.check3 !== "" && scwin.check3 !== "0") {
                return colorName;
            } else {
                return "#ffffff";
            }
        }
        if (colid === "acolor4") {
            // 자본금검증 당기
            scwin.check4 = dts_XBRL.getCellData(row, "CURTRM_TOTALSTOCKEQUITY");
            if (scwin.colorCnt > 0 && scwin.check4 !== "" && scwin.check4 !== "0") {
                return colorName;
            } else {
                return "#ffffff";
            }
        }
        if (colid === "acolor5") {
            // 자본금검증 전기
            scwin.check5 = dts_XBRL.getCellData(row, "FSTTRM_TOTALSTOCKEQUITY");
            if (scwin.colorCnt > 0 && scwin.check5 !== "" && scwin.check5 !== "0") {
                return colorName;
            } else {
                return "#ffffff";
            }
        }
        if (colid === "acolor6") {
            // 순손익검증 당기3개월
            scwin.check6 = dts_XBRL.getCellData(row, "CURTRM_EARNLOSS1");
