/**
 * @method
 * @name allDisCheck
 * @description all Dis Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allDisCheck = function() {
    // alert(eval('checkbox_'+num));

    for (let i = 0; i < 21; i++) {
        if (i === 0 || i === 1 || i === 2 || i === 7 || i === 8 || i === 12 || i === 15 || i === 20) {
            continue;
        }
        $p.getComponentById('checkbox_' + i).setValue(0);
    }
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    for (let i = 0; i < 21; i++) {
        if (i === 0 || i === 1 || i === 2 || i === 7 || i === 8 || i === 12 || i === 15 || i === 20) {
            continue;
        }
        $p.getComponentById('checkbox_' + i).setValue(1);
    }
};

/**
 * @method
 * @name showGridField
 * @description show Grid Field 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.showGridField = function(flag) {
    let id = "";
    if (flag === 'SHOW') {
        // grd_XBRL2.ColumnProp('1','Show') = true;
        // grd_XBRL2.ColumnProp('2','Show') = true;
        for (let i = 0; i < 21; i++) {
            id = i;
            if (i === 0 || i === 1 || i === 2 || i === 7 || i === 8 || i === 12 || i === 15 || i === 20) {
                continue;
            }
            $c.cm.setColumnProp(grd_XBRL2, i, 'Show', true);
        }
    } else {
        // grd_XBRL2.ColumnProp('1','Show') = false;
        // grd_XBRL2.ColumnProp('2','Show') = false;
        for (let i = 0; i < 21; i++) {
            id = i;
            if (i === 0 || i === 1 || i === 2 || i === 7 || i === 8 || i === 12 || i === 15 || i === 20) {
                continue;
            }
            $c.cm.setColumnProp(grd_XBRL2, i, 'Show', false);
        }
    }
};

/**
 * @method
 * @name checkBox
 * @description check Box 처리
 * @param {Number} i i
 * @returns {void}
 * @hidden N
 */
scwin.checkBox = function(i) {
    if ($p.getComponentById('checkbox_' + i).checked) {
        $c.cm.setColumnProp(grd_XBRL2, i, 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_XBRL2, i, 'Show', false);
    }
};
